1	package numeric
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9		"time"
10	)
11	
12	// failArchiveWrite 注入一个只让指定作业“成功归档”那一次落盘失败的故障：
13	// 该作业以 succeeded 状态（携带归档）保存时返回错误，模拟无法创建临时记录或
14	// 无法替换原记录；其随后的失败记录以及所有其他作业、其他状态的写入照常成功。
15	func failArchiveWrite(s *Store, id uint64) {
16		s.persistFault = func(j *storedJob) error {
17			if j.id == id && j.status == StatusSucceeded && j.archive != nil {
18				return errors.New("numeric(测试故障): 模拟结果归档写入失败")
19			}
20			return nil
21		}
22	}
23	
24	// 上游正常算出总和与平方和，但成功归档无法原子保存而最终失败时，所有仍在
25	// 排队、直接或间接等待它的作业必须立刻随之失败——无需任何新的提交、取消或
26	// 其他用户操作。失败信息遵循现有依赖规则，根因作业号指向最初归档写入失败的
27	// 作业；无关作业仍按原调度规则正常成功。
28	func TestArchiveWriteFailureCascadesWithoutFurtherAction(t *testing.T) {
29		dir := t.TempDir()
30		s, err := Open(dir, WithClock(newManualClock()))
31		if err != nil {
32			t.Fatal(err)
33		}
34		started, block, release, _, _ := gateCompute(t, s)
35		block(1)
36	
37		up := mustSubmit(t, s, SubmitRequest{
38			Submitter: "a", RequestID: "up", Values: []int64{1, 2, 3}, Seed: 9,
39		}) // 总和 6
40		waitStarted(t, started, up.ID)
41		failArchiveWrite(s, up.ID)
42	
43		child := mustSubmit(t, s, SubmitRequest{
44			Submitter: "a", RequestID: "child", Values: []int64{7},
45			Dependencies: []uint64{up.ID},
46		})
47		grand := mustSubmit(t, s, SubmitRequest{
48			Submitter: "a", RequestID: "grand", Values: []int64{8},
49			Dependencies: []uint64{child.ID},
50		})
51		// 与失败链无关、可独立运行的作业。
52		indep := mustSubmit(t, s, SubmitRequest{
53			Submitter: "a", RequestID: "indep", Values: []int64{5},
54		})
55	
56		// 放行后上游计算成功，但归档保存失败；此后不做任何提交/取消操作，
57		// 仅靠 Get 轮询（只读，不触发级联）就应观察到失败沿链条传播。
58		release(up.ID)
59	
60		u := waitStatus(t, s, up.ID, StatusFailed)
61		if !strings.Contains(u.FailureReason, "结果归档写入失败") {
62			t.Fatalf("upstream reason=%q, want 结果归档写入失败", u.FailureReason)
63		}
64		if u.Archive != nil || u.EffectiveValues != nil {
65			t.Fatalf("upstream must keep no usable success archive: %+v", u)
66		}
67		if u.FinishedAt.IsZero() || u.BlockerID != 0 {
68			t.Fatalf("upstream terminal fields wrong: finished=%s blocker=%d",
69				u.FinishedAt, u.BlockerID)
70		}
71		// 作业号、提交参数与依赖关系原样保留。
72		if u.ID != up.ID || u.RequestID != "up" || u.Seed != 9 ||
73			len(u.Values) != 3 || u.Values[2] != 3 || len(u.Dependencies) != 0 {
74			t.Fatalf("upstream params altered: %+v", u)
75		}
76	
77		// 直接下游：指出直接阻断者就是上游，根因也是上游。
78		c := waitStatus(t, s, child.ID, StatusFailed)
79		if c.BlockerID != up.ID {
80			t.Fatalf("child blocker=%d want upstream %d", c.BlockerID, up.ID)
81		}
82		if !strings.Contains(c.FailureReason, "直接上游作业 "+itoa(up.ID)) ||
83			!strings.Contains(c.FailureReason, "阻断") {
84			t.Fatalf("child must name direct upstream blocker: %q", c.FailureReason)
85		}
86		if strings.Contains(c.FailureReason, "阻断根因") {
87			t.Fatalf("direct downstream must not add a distinct root: %q", c.FailureReason)
88		}
89		if c.Archive != nil || c.FinishedAt.IsZero() || !c.StartedAt.IsZero() {
90			t.Fatalf("blocked child must never compute: started=%s finished=%s archive=%v",
91				c.StartedAt, c.FinishedAt, c.Archive)
92		}
93		if c.ID != child.ID || c.RequestID != "child" || len(c.Dependencies) != 1 ||
94			c.Dependencies[0] != up.ID || len(c.Values) != 1 || c.Values[0] != 7 {
95			t.Fatalf("child params/deps altered: %+v", c)
96		}
97	
98		// 间接下游：说明自己的直接上游（child），并通过根因作业号指回 up。
99		g := waitStatus(t, s, grand.ID, StatusFailed)
100		if g.BlockerID != up.ID {
101			t.Fatalf("grand blocker=%d want root %d", g.BlockerID, up.ID)
102		}
103		if !strings.Contains(g.FailureReason, "直接上游作业 "+itoa(child.ID)) ||
104			!strings.Contains(g.FailureReason, "阻断根因为作业 "+itoa(up.ID)) {
105			t.Fatalf("grand must name direct upstream %d and root %d: %q",
106				child.ID, up.ID, g.FailureReason)
107		}
108		if g.Archive != nil || g.FinishedAt.IsZero() {
109			t.Fatalf("grand terminal state wrong: finished=%s archive=%v",
110				g.FinishedAt, g.Archive)
111		}
112	
113		// 不在失败链上的作业照常计算并成功归档。
114		ind := waitStatus(t, s, indep.ID, StatusSucceeded)
115		if ind.Archive == nil || ind.Archive.Sum != 5 {
116			t.Fatalf("unrelated job must still succeed: %+v", ind)
117		}
118	
119		// 按提交人列举也应看到传播后的同一状态，顺序仍为提交先后。
120		list, err := s.List("a", time.Time{}, time.Time{})
121		if err != nil {
122			t.Fatal(err)
123		}
124		wantStatus := map[uint64]Status{
125			up.ID: StatusFailed, child.ID: StatusFailed,
126			grand.ID: StatusFailed, indep.ID: StatusSucceeded,
127		}
128		if len(list) != 4 {
129			t.Fatalf("list len=%d want 4", len(list))
130		}
131		for i, j := range list {
132			if j.ID != uint64(i+1) {
133				t.Fatalf("list not in submission order: pos %d id %d", i, j.ID)
134			}
135			if j.Status != wantStatus[j.ID] {
136				t.Fatalf("listed job %d status=%s want %s", j.ID, j.Status, wantStatus[j.ID])
137			}
138		}
139	
140		// 磁盘上：上游不得保留成功归档，失败链条均为 failed 记录。
141		for _, id := range []uint64{up.ID, child.ID, grand.ID} {
142			data, derr := os.ReadFile(filepath.Join(dir, jobFileName(id)))
143			if derr != nil {
144				t.Fatal(derr)
145			}
146			if !strings.Contains(string(data), `"status": "failed"`) ||
147				strings.Contains(string(data), `"archive"`) {
148				t.Fatalf("job %d disk record must be failed without archive:\n%s", id, data)
149			}
150		}
151	
152		// 重新打开同一归档：失败传播结果不丢失，上游依旧没有可用成功归档。
153		if err := s.Close(); err != nil {
154			t.Fatal(err)
155		}
156		s2, err := Open(dir)
157		if err != nil {
158			t.Fatal(err)
159		}
160		defer s2.Close()
161		for _, want := range []struct {
162			id      uint64
163			blocker uint64
164		}{
165			{up.ID, 0}, {child.ID, up.ID}, {grand.ID, up.ID},
166		} {
167			j, _ := s2.Get(want.id)
168			if j.Status != StatusFailed || j.BlockerID != want.blocker || j.Archive != nil {
169				t.Fatalf("after reopen job %d: status=%s blocker=%d archive=%v",
170					want.id, j.Status, j.BlockerID, j.Archive)
171			}
172		}
173	}
174	
175	// 一个作业等待多个上游时，只要其中一个归档写入失败，就不能因为其他上游仍在
176	// 排队或运行而继续等待；阻断者按已提交依赖列表顺序选取当时已失败的上游，
177	// 并作为根因向更下游传播。
178	func TestArchiveWriteFailureOneOfMultipleUpstreamsBlocks(t *testing.T) {
179		s, _ := openTestStore(t)
180		started, block, release, _, _ := gateCompute(t, s)
181		block(1, 2)
182	
183		upA := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "a", Values: []int64{1}})
184		waitStarted(t, started, upA.ID)
185		upB := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "b", Values: []int64{2}})
186		down := mustSubmit(t, s, SubmitRequest{
187			Submitter: "a", RequestID: "down", Values: []int64{3},
188			Dependencies: []uint64{upA.ID, upB.ID},
189		})
190		child := mustSubmit(t, s, SubmitRequest{
191			Submitter: "a", RequestID: "child", Values: []int64{4},
192			Dependencies: []uint64{down.ID},
193		})
194	
195		// upA 计算成功并归档成功；upB 计算成功但归档写入失败。
196		failArchiveWrite(s, upB.ID)
197		release(upA.ID)
198		waitStatus(t, s, upA.ID, StatusSucceeded)
199		release(upB.ID)
200		waitStatus(t, s, upB.ID, StatusFailed)
201	
202		// down 不能因 upA 已成功、或“还在等 upB”而继续排队：立即失败，
203		// 阻断者为列表中当时已失败的 upB。
204		d := waitStatus(t, s, down.ID, StatusFailed)
205		if d.BlockerID != upB.ID {
206			t.Fatalf("down blocker=%d want failed-in-list-order upstream %d",
207				d.BlockerID, upB.ID)
208		}
209		if !strings.Contains(d.FailureReason, "直接上游作业 "+itoa(upB.ID)) {
210			t.Fatalf("down reason must name upB: %q", d.FailureReason)
211		}
212		// 更下游通过根因作业号指向 upB。
213		c2 := waitStatus(t, s, child.ID, StatusFailed)
214		if c2.BlockerID != upB.ID {
215			t.Fatalf("child blocker=%d want root %d", c2.BlockerID, upB.ID)
216		}
217	}
